inline Config MakeConfig(userver::formats::parse::To<Config>) {
  return MakeConfig();
}

template <typename T>
inline void ApplyCustomProperties(
    const userver::formats::yaml::Value& value, T& config) {
  if (!value.IsObject()) return;
  const auto parsed = value.As<T>();
  for (const auto& [name, property] : parsed.properties) {
    config.properties.insert_or_assign(name, property);
  }
}

