inline servicelib::api::Environment ParseEnvironment(
    std::string_view value) {
  if (value.empty()) return servicelib::api::Environment::kUndefined;
  if (value == "local") return servicelib::api::Environment::kLocal;
  if (value == "debug") return servicelib::api::Environment::kDebug;
  if (value == "staging") return servicelib::api::Environment::kStaging;
  if (value == "production") return servicelib::api::Environment::kProduction;
  throw std::invalid_argument("invalid service environment: " +
                              std::string{value});
}

inline int ParseEnvironmentInt(const char* name, const char* value) {
  int result{};
  const std::string_view text{value};
  const auto [end, error] =
      std::from_chars(text.data(), text.data() + text.size(), result);
  if (error != std::errc{} || end != text.data() + text.size()) {
    throw std::invalid_argument(std::string{"invalid integer in "} + name);
  }
  return result;
}

inline void ApplyEnvironment(Config& config) {
  if (const auto* value = std::getenv("ANALYTICS_SCHEDULE_ENABLED")) {
    const std::string_view parsed{value};
    if (parsed != "true" && parsed != "false") {
      throw std::invalid_argument("invalid boolean in ANALYTICS_SCHEDULE_ENABLED");
    }
    config.endpoints.analyticsSchedule.enabled = parsed == "true";
  }
  if (const auto* value = std::getenv("ANALYTICS_SCHEDULE_MISSED_RUN_POLICY")) {
    config.endpoints.analyticsSchedule.missedRunPolicy =
        userver::formats::yaml::FromString(value).As<servicelib::api::ScheduleMissedRunPolicy>();
  }
  if (const auto* value = std::getenv("ANALYTICS_SCHEDULE_OVERLAP_POLICY")) {
    config.endpoints.analyticsSchedule.overlapPolicy =
        userver::formats::yaml::FromString(value).As<servicelib::api::ScheduleOverlapPolicy>();
  }
  if (const auto* value = std::getenv("ANALYTICS_SCHEDULE_SCHEDULE")) {
    config.endpoints.analyticsSchedule.schedule = value;
  }
  if (const auto* value = std::getenv("ANALYTICS_SCHEDULE_TIMEZONE")) {
    config.endpoints.analyticsSchedule.timezone = value;
  }
  if (const auto* value = std::getenv("ANALYTICS_SCHEDULE_TRACING_ENABLED")) {
    const std::string_view parsed{value};
    if (parsed != "true" && parsed != "false") {
      throw std::invalid_argument("invalid boolean in ANALYTICS_SCHEDULE_TRACING_ENABLED");
    }
    config.endpoints.analyticsSchedule.tracingEnabled = parsed == "true";
  }
  if (const auto* value = std::getenv("ANALYTICS_SERVICE_DEFAULT_GRPC_TIMEOUT")) {
    config.services.analyticsService.defaultGrpcTimeout =
        ParseEnvironmentInt("ANALYTICS_SERVICE_DEFAULT_GRPC_TIMEOUT", value);
  }
  if (const auto* value = std::getenv("ANALYTICS_SERVICE_ENVIRONMENT")) {
    config.services.analyticsService.environment = ParseEnvironment(value);
  }
  if (const auto* value = std::getenv("ANALYTICS_SERVICE_GRPC_HOST")) {
    config.services.analyticsService.grpcHost = value;
  }
  if (const auto* value = std::getenv("ANALYTICS_SERVICE_GRPC_PORT")) {
    config.services.analyticsService.grpcPort =
        ParseEnvironmentInt("ANALYTICS_SERVICE_GRPC_PORT", value);
  }
  if (const auto* value = std::getenv("ANALYTICS_SERVICE_HTTP_HOST")) {
    config.services.analyticsService.httpHost = value;
  }
  if (const auto* value = std::getenv("ANALYTICS_SERVICE_HTTP_PORT")) {
    config.services.analyticsService.httpPort =
        ParseEnvironmentInt("ANALYTICS_SERVICE_HTTP_PORT", value);
  }
  if (const auto* value = std::getenv("ORDER_EVENTS_BROKERS")) {
    config.dataConnectors.orderEvents.brokers = value;
  }
  if (const auto* value = std::getenv("ORDER_EVENTS_PASSWORD")) {
    config.dataConnectors.orderEvents.password = value;
  }
  if (const auto* value = std::getenv("ORDER_EVENTS_SASL_MECHANISM")) {
    config.dataConnectors.orderEvents.saslMechanism =
        userver::formats::yaml::FromString(value).As<servicelib::api::KafkaSaslMechanism>();
  }
  if (const auto* value = std::getenv("ORDER_EVENTS_SECURITY_PROTOCOL")) {
    config.dataConnectors.orderEvents.securityProtocol =
        userver::formats::yaml::FromString(value).As<servicelib::api::KafkaSecurityProtocol>();
  }
  if (const auto* value = std::getenv("ORDER_EVENTS_USERNAME")) {
    config.dataConnectors.orderEvents.username = value;
  }
  if (const auto* value = std::getenv("ORDER_PROCESSED_ENABLED")) {
    const std::string_view parsed{value};
    if (parsed != "true" && parsed != "false") {
      throw std::invalid_argument("invalid boolean in ORDER_PROCESSED_ENABLED");
    }
    config.endpoints.orderProcessed.enabled = parsed == "true";
  }
  ApplyEnvironment(config.custom);
}

